/* 학습 해설
 * 블록 완료 경로: 현재 CPU·다른 CPU·softirq 선택
 * 장치 완료 인터럽트를 받은 CPU와 요청을 보낸 CPU가 다를 수 있습니다. 어디에서 완료 후처리를 할지 정하면 캐시 재사용에 영향을 주지만, 다른 CPU로 알리는 비용과 사용 가능한 CPU 상태도 고려해야 합니다.
 * 먼저 rq 상태를 COMPLETE로 표시합니다. hctx에 ctx가 하나이고 그 ctx CPU가 현재 CPU이거나 요청이 POLLED이면 false입니다. blk_mq_complete_need_ipi가 참이면 IPI 경로로 넘기고 true입니다. 그 외 하드웨어 큐가 하나면 현재 CPU softirq 목록에 넣고 true입니다. 아니면 false입니다. 상위 blk_mq_complete_request는 이 함수가 false일 때만 mq_ops->complete를 직접 호출합니다. true가 반드시 다른 CPU에서 이미 완료했다는 뜻은 아닙니다.
 * POLLED 요청은 false → 직접 callback 경로로 그리세요. IPI 불필요·하드웨어 큐 1개이면 true → softirq 후처리 경로입니다. CPU 간 IPI 판정은 SMP 및 SAME_COMP가 필요하고 강제 IRQ 스레드에서는 피합니다. 같은 CPU이거나 SAME_FORCE가 없고 캐시 및 CPU capacity를 공유하면 보통 현 위치에서 처리하며 대상 CPU가 offline이면 보내지 않습니다.
 */
bool blk_mq_complete_request_remote(struct request *rq)
{
	WRITE_ONCE(rq->state, MQ_RQ_COMPLETE);

	/*
	 * For request which hctx has only one ctx mapping,
	 * or a polled request, always complete locally,
	 * it's pointless to redirect the completion.
	 */
	if ((rq->mq_hctx->nr_ctx == 1 &&
	     rq->mq_ctx->cpu == raw_smp_processor_id()) ||
	     rq->cmd_flags & REQ_POLLED)
		return false;

	if (blk_mq_complete_need_ipi(rq)) {
		blk_mq_complete_send_ipi(rq);
		return true;
	}

	if (rq->q->nr_hw_queues == 1) {
		blk_mq_raise_softirq(rq);
		return true;
	}
	return false;
}
EXPORT_SYMBOL_GPL(blk_mq_complete_request_remote);

/* 학습 해설
 * 블록 요청 종료: 완료 callback이 객체를 계속 소유하는 경우
 * I/O가 끝났다고 모든 요청 객체를 무조건 즉시 해제할 수는 없습니다. 상위 코드가 요청의 결과를 더 처리하거나 재사용하도록 callback이 소유권을 유지하는 계약이 있을 수 있습니다.
 * __blk_mq_end_request는 시간 기록이 필요하면 통계·스케줄러·I/O 회계를 갱신하고 blk_mq_finish_request를 호출합니다. end_io가 있으면 rq_qos_done 후 callback에 rq와 error를 전달합니다. callback 반환이 RQ_END_IO_FREE일 때만 blk_mq_free_request를 호출합니다. callback이 없으면 바로 free 경로입니다. 공개 blk_mq_end_request는 먼저 전체 잔여 바이트를 blk_update_request로 처리하고 아직 남는다고 반환되면 BUG 후 내부 종료 함수를 호출합니다.
 * end_io가 NONE을 반환하는 경우와 FREE를 반환하는 경우를 나눠 그리세요. 둘 다 요청 완료 후처리는 진행하지만 이 위치에서 객체를 free하는지는 다릅니다. callback이 free를 선택한 뒤에는 호출자가 rq를 계속 읽을 수 있다고 가정하지 않습니다. error는 해당 요청의 I/O 결과를 callback에 전달하는 값입니다.
 */
inline void __blk_mq_end_request(struct request *rq, blk_status_t error)
{
	if (blk_mq_need_time_stamp(rq))
		__blk_mq_end_request_acct(rq, blk_time_get_ns());

	blk_mq_finish_request(rq);

	if (rq->end_io) {
		rq_qos_done(rq->q, rq);
		if (rq->end_io(rq, error) == RQ_END_IO_FREE)
			blk_mq_free_request(rq);
	} else {
		blk_mq_free_request(rq);
	}
}
EXPORT_SYMBOL(__blk_mq_end_request);

void blk_mq_end_request(struct request *rq, blk_status_t error)
{
	if (blk_update_request(rq, error, blk_rq_bytes(rq)))
		BUG();
	__blk_mq_end_request(rq, error);
}
EXPORT_SYMBOL(blk_mq_end_request);

