/* 학습 해설
 * BIO 분할: 512바이트 섹터 단위와 데이터 공유 수명
 * 하나의 I/O가 장치 제한보다 크면 앞부분과 나머지로 나누어 제출해야 합니다. 이때 실제 데이터까지 복사하지 않고 범위를 나누어 가리킬 수 있지만, 공유하는 데이터와 벡터의 수명은 더 신중히 유지해야 합니다.
 * bio_split은 sectors가 0 이하이거나 전체 bio 섹터 수 이상이면 BUG입니다. ZONE_APPEND는 경고 후 NULL입니다. bio_alloc_clone 실패도 NULL입니다. 성공하면 split의 크기를 sectors << 9로 설정하고 무결성 정보가 있으면 trim합니다. 원래 bio는 그 크기만큼 bio_advance하여 나머지를 나타내게 합니다. 완료 추적 플래그도 새 split에 전달한 뒤 split을 반환합니다.
 * 전체 16섹터 BIO에서 4섹터를 나누면 split은 4×512=2048바이트, 원래 BIO는 뒤의 12섹터 범위가 됩니다. 여기의 섹터 단위는 장치의 논리 블록 크기와 무관하게 코드의 <<9, 즉 512바이트입니다. 원문 주석에 따르면 discard를 제외한 split은 원래 bi_io_vec를 가리키므로 split보다 원래 bio와 bio_set을 먼저 해제하면 안 됩니다.
 */
struct bio *bio_split(struct bio *bio, int sectors,
		      gfp_t gfp, struct bio_set *bs)
{
	struct bio *split;

	BUG_ON(sectors <= 0);
	BUG_ON(sectors >= bio_sectors(bio));

	/* Zone append commands cannot be split */
	if (WARN_ON_ONCE(bio_op(bio) == REQ_OP_ZONE_APPEND))
		return NULL;

	split = bio_alloc_clone(bio->bi_bdev, bio, gfp, bs);
	if (!split)
		return NULL;

	split->bi_iter.bi_size = sectors << 9;

	if (bio_integrity(split))
		bio_integrity_trim(split);

	bio_advance(bio, split->bi_iter.bi_size);

	if (bio_flagged(bio, BIO_TRACE_COMPLETION))
		bio_set_flag(split, BIO_TRACE_COMPLETION);

/* 학습 해설
 * 패킷 clone: 메타데이터는 따로, 실제 데이터는 공유
 * 같은 패킷을 여러 경로에서 관찰하거나 전달할 때 본문을 매번 복사하면 메모리와 복사 시간이 듭니다. 패킷을 설명하는 sk_buff 객체만 별도로 만들고 데이터 공간은 공유하면 그 비용을 줄일 수 있습니다.
 * skb_clone은 먼저 skb_orphan_frags 실패를 확인합니다. fclone 원본이고 쌍의 참조가 1이면 미리 마련된 skb2를 사용하며 아니면 별도 sk_buff를 할당합니다. pfmemalloc이면 할당 플래그를 보강합니다. __skb_clone은 링크·소켓·destructor 등을 새 객체 규칙에 맞추고 길이 및 head/data/tail/end 같은 위치 정보를 복사합니다. 새 객체 users는 1로 두고 공유 데이터 dataref를 증가시키며 양쪽을 cloned 상태로 표시합니다.
 * 원본 A와 clone B를 두 상자로 그린 뒤 둘의 head/data 화살표가 같은 데이터 공간으로 향하게 하세요. B의 메타데이터가 별도라는 것만으로 B를 통해 본문 바이트를 수정해도 A가 영향받지 않는다고 판단하면 안 됩니다. 데이터 쓰기 전 공유 해제나 적절한 writable 확보 경로가 필요합니다.
 */
struct sk_buff *skb_clone(struct sk_buff *skb, gfp_t gfp_mask)
{
	struct sk_buff_fclones *fclones = container_of(skb,
						       struct sk_buff_fclones,
						       skb1);
	struct sk_buff *n;

	if (skb_orphan_frags(skb, gfp_mask))
		return NULL;

	if (skb->fclone == SKB_FCLONE_ORIG &&
	    refcount_read(&fclones->fclone_ref) == 1) {
		n = &fclones->skb2;
		refcount_set(&fclones->fclone_ref, 2);
		n->fclone = SKB_FCLONE_CLONE;
	} else {
		if (skb_pfmemalloc(skb))
			gfp_mask |= __GFP_MEMALLOC;

		n = kmem_cache_alloc(net_hotdata.skbuff_cache, gfp_mask);
		if (!n)
			return NULL;

		n->fclone = SKB_FCLONE_UNAVAILABLE;
	}

/* 학습 해설
 * 패킷 전체 복사: 흩어진 데이터를 새 선형 버퍼로 모으기
 * 공유 패킷의 본문을 독립적으로 바꾸려면 새 데이터 저장 공간이 필요할 수 있습니다. 원본이 선형 머리와 여러 fragment로 나뉘어 있어도 복사 결과를 하나의 선형 데이터 영역으로 만들 수 있습니다.
 * skb_copy는 fragment가 읽을 수 없으면 NULL이고 GSO_FRAGLIST 형식도 경고 후 NULL입니다. 원래 headroom을 기억하고 skb_end_offset+data_len 크기로 새 skb를 할당합니다. skb_reserve로 headroom을 만들고 skb_put으로 데이터 길이를 확보합니다. skb_copy_bits를 -headerlen부터 호출해 headroom과 전체 패킷 길이를 새 head에 복사하고 skb_copy_header로 메타데이터를 옮깁니다. 정상 전제에서 copy_bits 오류는 BUG_ON 대상입니다.
 * 원본 headroom=32, 패킷 len=1000이라고 가정하면 데이터 앞 32바이트도 함께 복사하며 새 data는 새 head에서 32바이트 뒤입니다. 원본 data_len은 비선형 영역의 길이여서 새 할당 크기 계산에 포함됩니다. 이 API의 실패 반환 NULL을 확인하고 성공 객체의 수명을 나중에 정리하세요.
 */
struct sk_buff *skb_copy(const struct sk_buff *skb, gfp_t gfp_mask)
{
	struct sk_buff *n;
	unsigned int size;
	int headerlen;

	if (!skb_frags_readable(skb))
		return NULL;

	if (WARN_ON_ONCE(skb_shinfo(skb)->gso_type & SKB_GSO_FRAGLIST))
		return NULL;

	headerlen = skb_headroom(skb);
	size = skb_end_offset(skb) + skb->data_len;
	n = __alloc_skb(size, gfp_mask,
			skb_alloc_rx_flag(skb), NUMA_NO_NODE);
	if (!n)
		return NULL;

	/* Set the data pointer */
	skb_reserve(n, headerlen);
	/* Set the tail pointer and length */
	skb_put(n, skb->len);

	BUG_ON(skb_copy_bits(skb, -headerlen, n->head, headerlen + skb->len));

/* 학습 해설
 * 패킷 공간 확보: reserve·put·push의 위치 변화
 * 네트워크 계층은 데이터 앞에 헤더를 붙이고 뒤에 본문을 쓸 공간이 필요합니다. 이미 확보한 버퍼 안에서 headroom과 tailroom을 관리하면 매번 데이터를 옮기지 않고 패킷 범위를 조정할 수 있습니다.
 * 빈 skb에서 skb_reserve는 data와 tail을 같은 길이만큼 앞으로 이동하며 len을 늘리지 않습니다. skb_put은 기존 tail 주소를 반환하고 tail과 len을 늘리며 end를 넘으면 panic 경로입니다. 선형 버퍼 전제도 검사합니다. skb_push는 data를 뒤로 이동하고 len을 늘리며 head보다 앞서면 panic입니다. 두 함수 모두 자동으로 메모리를 늘려 주거나 새 영역을 0으로 채우는 함수가 아닙니다.
 * head 기준 전체 공간 128, 초기 data=tail=0,len=0인 단순 모델을 보세요. reserve(32) 뒤 data=tail=32,len=0입니다. put(40) 뒤 data=32,tail=72,len=40이고 반환은 이전 tail 위치 32입니다. push(20) 뒤 data=12,tail=72,len=60입니다. 앞 헤더 20바이트를 쓸 자리를 확보한 것입니다.
 */
void *skb_put(struct sk_buff *skb, unsigned int len)
{
	void *tmp = skb_tail_pointer(skb);
	SKB_LINEAR_ASSERT(skb);
	skb->tail += len;
	skb->len  += len;
	if (unlikely(skb->tail > skb->end))
		skb_over_panic(skb, len, __builtin_return_address(0));
	return tmp;
}
EXPORT_SYMBOL(skb_put);

/**
 *	skb_push - add data to the start of a buffer
 *	@skb: buffer to use
 *	@len: amount of data to add
 *
 *	This function extends the used data area of the buffer at the buffer
 *	start. If this would exceed the total buffer headroom the kernel will
 *	panic. A pointer to the first byte of the extra data is returned.
 */
void *skb_push(struct sk_buff *skb, unsigned int len)
{
	skb->data -= len;
	skb->len  += len;
	if (unlikely(skb->data < skb->head))

/* 학습 해설
 * 패킷 앞부분 소비: pull의 길이 검사와 비선형 영역
 * 헤더를 해석한 뒤 그 부분을 소비하면 다음 프로토콜 계층은 payload부터 읽어야 합니다. 포인터를 움직이는 비용은 작지만 전체 패킷 길이와 바로 접근 가능한 선형 영역의 길이를 구별해야 합니다.
 * skb_pull은 헤더의 skb_pull_inline에 위임합니다. 요청 len이 전체 skb->len보다 크면 NULL이며 변경하지 않습니다. 아니면 __skb_pull이 전체 len을 줄이고 줄어든 값이 data_len보다 작으면 BUG 경로입니다. 정상일 때 data를 앞으로 len만큼 옮겨 새 시작 주소를 반환합니다. data_len은 fragment 등에 있는 비선형 데이터 길이이므로 감소한 전체 길이가 그것보다 작아지면 선형 영역보다 더 많이 pull한 셈입니다.
 * 전체 길이 1000, data_len=700이면 선형 머리는 300바이트입니다. pull(100)은 새 전체 길이 900으로 가능하지만 pull(400)은 전체 길이보다 작아도 선형 머리를 넘으므로 __skb_pull 조건을 위반합니다. 필요한 헤더가 선형 영역에 있는지 pskb_may_pull 같은 준비 경로를 사용하는 계약을 함께 확인하세요.
 */
void *skb_pull(struct sk_buff *skb, unsigned int len)
{
	return skb_pull_inline(skb, len);
}
EXPORT_SYMBOL(skb_pull);

/**
 *	skb_pull_data - remove data from the start of a buffer returning its
 *	original position.
 *	@skb: buffer to use
 *	@len: amount of data to remove
 *
 *	This function removes data from the start of a buffer, returning
 *	the memory to the headroom. A pointer to the original data in the buffer
 *	is returned after checking if there is enough data to pull. Once the
 *	data has been pulled future pushes will overwrite the old data.
 */
void *skb_pull_data(struct sk_buff *skb, size_t len)
{
	void *data = skb->data;

	if (skb->len < len)
		return NULL;

	skb_pull(skb, len);

/* 학습 해설
 * 부팅 전용 메모리 해제: 비동기 초기화가 끝날 때까지 기다리기
 * 부팅할 때만 쓰는 코드를 계속 메모리에 남기면 공간을 낭비하지만 초기화 작업이 아직 그 코드를 실행 중일 때 해제하면 사용 중인 메모리를 없애는 오류가 됩니다. 비동기 작업과 추적 도구의 참조까지 정리하는 순서가 필요합니다.
 * kernel_init은 kthreadd_done 완료를 기다린 뒤 kernel_init_freeable을 실행합니다. 이어 async_synchronize_full로 비동기 __init 작업 종료를 기다립니다. system_state를 FREEING_INITMEM으로 바꾸고 kprobe·ftrace·kgdb의 init 메모리 관련 정리 및 boot config 정리를 한 뒤 free_initmem, mark_readonly를 수행합니다. 커널 매핑이 정해진 뒤 pti_finalize를 하고 SYSTEM_RUNNING으로 바꿉니다. NUMA 기본 정책과 RCU 부팅 종료, sysctl 인자 처리가 이후 사용자 init 선택보다 앞에 있습니다.
 * 비동기 초기화 A가 아직 init 코드 주소를 사용한다는 시간선을 그리세요. 기다림 없이 먼저 free하면 A가 재사용된 메모리를 실행하거나 읽을 위험이 있습니다. 여기서 해제하는 것은 부팅 전용 영역이며 모든 커널 코드나 프로세스 메모리를 지우는 작업이 아닙니다. SYSTEM_RUNNING 대입도 사용자 init 실행 성공을 미리 보장하지 않습니다.
 */
static int __ref kernel_init(void *unused)
{
	int ret;

	/*
	 * Wait until kthreadd is all set-up.
	 */
	wait_for_completion(&kthreadd_done);

	kernel_init_freeable();
	/* need to finish all async __init code before freeing the memory */
	async_synchronize_full();

	system_state = SYSTEM_FREEING_INITMEM;
	kprobe_free_init_mem();
	ftrace_free_init_mem();
	kgdb_free_init_mem();
	exit_boot_config();
	free_initmem();
	mark_readonly();

	/*
	 * Kernel mappings are now finalized - update the userspace page-table
	 * to finalize PTI.
	 */
	pti_finalize();

/* 학습 해설
 * 최초 사용자 init 선택: 명시한 경로 실패와 기본 후보 순서
 * 커널 초기화 뒤에는 사용자 공간에서 서비스를 시작하고 프로세스를 관리할 프로그램이 필요합니다. 지정한 init과 기본 후보를 어떤 순서로 시도하고 실패를 어떻게 취급하는지가 부팅 결과를 바꿉니다.
 * run_init_process는 argv_init[0]에 실행 경로를 넣고 인자 및 환경을 추적한 뒤 kernel_execve의 결과를 반환합니다. kernel_init은 ramdisk_execute_command가 있으면 먼저 시도하고 실패를 로그로 남긴 뒤 계속합니다. execute_command로 명시한 init은 실패하면 panic합니다. 그 다음 비어 있지 않은 CONFIG_DEFAULT_INIT을 시도하며 실패하면 기본 후보로 넘어갑니다. 후보는 /sbin/init, /etc/init, /bin/init, /bin/sh 순서이고 모두 실패하면 panic입니다.
 * 명시한 execute_command가 있는데 실행 실패한 경우와 CONFIG_DEFAULT_INIT 실패를 비교하세요. 앞은 요청한 init 실패로 멈추지만 뒤는 기본 후보를 계속 시도합니다. try_to_run_init_process는 실패 중 -ENOENT 외의 오류를 따로 로그로 남기고 결과를 그대로 돌려줍니다. 각 실행 시도는 같은 argv_init의 0번째 항목을 해당 경로로 갱신합니다.
 */
static int run_init_process(const char *init_filename)
{
	const char *const *p;

	argv_init[0] = init_filename;
	pr_info("Run %s as init process\n", init_filename);
	pr_debug("  with arguments:\n");
	for (p = argv_init; *p; p++)
		pr_debug("    %s\n", *p);
	pr_debug("  with environment:\n");
	for (p = envp_init; *p; p++)
		pr_debug("    %s\n", *p);
	return kernel_execve(init_filename, argv_init, envp_init);
}

static int try_to_run_init_process(const char *init_filename)
{
	int ret;

	ret = run_init_process(init_filename);

	if (ret && ret != -ENOENT) {
		pr_err("Starting init: %s exists but couldn't execute it (error %d)\n",
		       init_filename, ret);
	}

/* 학습 해설
 * 파일 열기: descriptor 번호 예약과 파일 객체 연결
 * 프로그램에 작은 정수 fd를 돌려주려면 파일 이름 해석과 실제 file 객체 생성뿐 아니라 fd 표의 빈 자리를 확보해야 합니다. 번호 예약 뒤 실제 열기가 실패하면 예약을 반환하지 않을 경우 사용 가능한 번호를 잃게 됩니다.
 * do_sys_openat2는 build_open_flags 오류면 바로 반환합니다. getname 오류 포인터는 PTR_ERR로 돌려줍니다. 이름을 얻은 뒤 get_unused_fd_flags로 번호를 예약합니다. fd가 음수면 실제 열기는 시도하지 않고 이름을 정리합니다. 번호를 얻었으면 do_filp_open을 호출하고 실패 시 put_unused_fd로 예약을 돌려주며 파일 오류 코드를 fd에 넣습니다. 성공 시 fd_install로 번호와 file 객체를 연결합니다. 마지막에는 putname 후 fd를 반환합니다.
 * fd=3 예약 성공 → do_filp_open 실패 상황에서 3을 사용자에게 성공값으로 돌려주면 안 됩니다. 예약을 취소하고 PTR_ERR(f)를 반환합니다. 성공 경로에서는 3이라는 정수와 file 객체 포인터를 표에 연결합니다. 번호 자체가 디스크 주소나 file 구조체 주소인 것은 아닙니다.
 */
static long do_sys_openat2(int dfd, const char __user *filename,
			   struct open_how *how)
{
	struct open_flags op;
	int fd = build_open_flags(how, &op);
	struct filename *tmp;

	if (fd)
		return fd;

	tmp = getname(filename);
	if (IS_ERR(tmp))
		return PTR_ERR(tmp);

	fd = get_unused_fd_flags(how->flags);
	if (fd >= 0) {
		struct file *f = do_filp_open(dfd, tmp, &op);
		if (IS_ERR(f)) {
			put_unused_fd(fd);
			fd = PTR_ERR(f);
		} else {
			fd_install(fd, f);
		}
	}
	putname(tmp);
	return fd;

/* 학습 해설
 * cgroup 이동 권한: 공통 조상과 위임 경계
 * 프로세스를 다른 cgroup으로 옮기는 권한을 목적지 하나만으로 판단하면 위임받지 않은 다른 하위 트리에서 작업을 빼오는 일이 가능해질 수 있습니다. 이동의 출발점과 도착점이 만나는 계층 경계를 확인해야 합니다.
 * cgroup_procs_write_permission은 cgroup_mutex를 이미 잡았다는 조건을 lockdep으로 확인합니다. src에서 시작해 dst가 현재 후보의 자손이 될 때까지 부모로 올라가 공통 조상을 찾습니다. 그 조상의 cgroup.procs inode에 대해 cgroup_may_write로 쓰기 권한을 검사합니다. namespace 위임 경계가 켜져 있으면 src와 dst가 모두 해당 namespace 루트 아래인지 확인하며 하나라도 밖이면 -ENOENT입니다. 전부 통과하면 0입니다.
 * 루트 아래 A와 B가 있고 A/x에서 A/y로 옮기면 공통 조상은 A입니다. A/x에서 B/y로 옮기면 더 위의 루트가 공통 조상입니다. 이 검사는 이동이 걸치는 권한 경계를 반영합니다. helper는 자체적으로 cgroup_mutex를 잡지 않으므로 호출자의 잠금 의무와 lockdep 검사를 구별하세요.
 */
static int cgroup_procs_write_permission(struct cgroup *src_cgrp,
					 struct cgroup *dst_cgrp,
					 struct super_block *sb,
					 struct cgroup_namespace *ns)
{
	struct cgroup *com_cgrp = src_cgrp;
	int ret;

	lockdep_assert_held(&cgroup_mutex);

	/* find the common ancestor */
	while (!cgroup_is_descendant(dst_cgrp, com_cgrp))
		com_cgrp = cgroup_parent(com_cgrp);

	/* %current should be authorized to migrate to the common ancestor */
	ret = cgroup_may_write(com_cgrp, sb);
	if (ret)
		return ret;

	/*
	 * If namespaces are delegation boundaries, %current must be able
	 * to see both source and destination cgroups from its namespace.
	 */
	if ((cgrp_dfl_root.flags & CGRP_ROOT_NS_DELEGATE) &&
	    (!cgroup_is_descendant(src_cgrp, ns->root_cset->dfl_cgrp) ||
	     !cgroup_is_descendant(dst_cgrp, ns->root_cset->dfl_cgrp)))

/* 학습 해설
 * cgroup 쓰기 자격: 파일을 열 때의 자격으로 검사하고 복원하기
 * cgroup 제어 파일 descriptor가 상속되거나 전달됐을 때 현재 호출자의 자격만으로 위임 검사를 하면 의도한 파일 권한 경계를 벗어날 수 있습니다. 이 구현은 파일을 열 때 저장한 자격을 특정 검사 동안 적용합니다.
 * __cgroup_procs_write는 살아 있는 목적지 cgroup 잠금을 얻지 못하면 -ENODEV입니다. 태스크 선택 준비의 오류는 잠금 해제로 갑니다. 성공하면 css_set_lock 아래 출발 cgroup을 찾습니다. override_creds(of->file->f_cred)로 파일 자격을 적용하고 cgroup_attach_permissions를 호출한 뒤 즉시 revert_creds로 이전 자격을 복원합니다. 권한 오류면 finish로, 성공이면 cgroup_attach_task를 실행합니다. 그 뒤 태스크 준비 정리와 cgroup 잠금 해제를 거칩니다.
 * 권한 검사가 -EACCES를 반환하는 시간선을 그리세요. 이 경우도 revert_creds를 먼저 실행하고 out_finish로 갑니다. 실제 태스크 이동은 하지 않지만 선택 과정의 자원 및 잠금은 정리합니다. cgroup.procs wrapper는 threadgroup=true, cgroup.threads wrapper는 false를 전달합니다.
 */
static ssize_t __cgroup_procs_write(struct kernfs_open_file *of, char *buf,
				    bool threadgroup)
{
	struct cgroup_file_ctx *ctx = of->priv;
	struct cgroup *src_cgrp, *dst_cgrp;
	struct task_struct *task;
	const struct cred *saved_cred;
	ssize_t ret;
	bool threadgroup_locked;

	dst_cgrp = cgroup_kn_lock_live(of->kn, false);
	if (!dst_cgrp)
		return -ENODEV;

	task = cgroup_procs_write_start(buf, threadgroup, &threadgroup_locked);
	ret = PTR_ERR_OR_ZERO(task);
	if (ret)
		goto out_unlock;

	/* find the source cgroup */
	spin_lock_irq(&css_set_lock);
	src_cgrp = task_cgroup_from_root(task, &cgrp_dfl_root);
	spin_unlock_irq(&css_set_lock);

	/*
	 * Process and thread migrations follow same delegation rule. Check
	 * permissions using the credentials from file open to protect against
	 * inherited fd attacks.
	 */

/* 학습 해설
 * TCP 편차와 RTO: 지연 감소에도 단순 대칭이 아닌 갱신
 * 평균 왕복 시간만큼만 기다리면 조금 늦어진 ACK를 손실로 오해할 수 있습니다. 지연 변동 폭을 반영하되 한 번 빨라진 측정 때문에 재전송 한도를 너무 빠르게 낮추는 것도 피해야 합니다.
 * tcp_rtt_estimator는 RTT 오차에서 mdev_us의 1/4을 반영해 편차를 갱신합니다. RTT가 감소한 쪽에서는 오차 절댓값에서 mdev의 1/4을 뺀 값이 양수일 때 다시 8로 나누어 완만하게 증가시킵니다. mdev가 구간 최대를 넘으면 mdev_max를 높이고 필요하면 rttvar도 높입니다. snd_una가 rtt_seq를 지나 새 구간이 되면 rttvar와 구간 최대의 차이를 1/4 줄일 수 있고 기준을 재설정합니다. tcp_set_rto는 (srtt_us>>3)+rttvar_us를 jiffies로 바꾸고 TCP_RTO_MAX 상한을 적용합니다.
 * 기존 실제 RTT=100000μs, mdev=40000에서 새 RTT=120000이면 오차 20000-10000=10000을 더해 mdev=50000입니다. 새 RTT가 80000이면 절댓값 20000-10000=10000을 다시 8로 나눠 1250만 더하므로 mdev=41250입니다. 같은 20ms 차이도 방향에 따라 다르게 처리합니다.
 */
static void tcp_set_rto(struct sock *sk)
{
	const struct tcp_sock *tp = tcp_sk(sk);
	/* Old crap is replaced with new one. 8)
	 *
	 * More seriously:
	 * 1. If rtt variance happened to be less 50msec, it is hallucination.
	 *    It cannot be less due to utterly erratic ACK generation made
	 *    at least by solaris and freebsd. "Erratic ACKs" has _nothing_
	 *    to do with delayed acks, because at cwnd>2 true delack timeout
	 *    is invisible. Actually, Linux-2.4 also generates erratic
	 *    ACKs in some circumstances.
	 */
	inet_csk(sk)->icsk_rto = __tcp_set_rto(tp);

	/* 2. Fixups made earlier cannot be right.
	 *    If we do not estimate RTO correctly without them,
	 *    all the algo is pure shit and should be replaced
	 *    with correct one. It is exactly, which we pretend to do.
	 */

	/* NOTE: clamping at TCP_RTO_MIN is not required, current algo
	 * guarantees that rto is higher.
	 */
	tcp_bound_rto(sk);
}

/* 학습 해설
 * TCP pacing: 윈도와 RTT를 전송률로 바꾸기
 * 한 번에 보낼 수 있는 데이터 양만 정하면 그 데이터를 순간적으로 몰아보내 큐가 길어질 수 있습니다. pacing은 보내는 속도를 정해 시간에 걸쳐 전송을 배치하도록 돕습니다.
 * tcp_update_pacing_rate는 MSS와 μs 단위 환산 및 srtt의 8배 저장 배율을 반영한 rate를 만듭니다. cwnd가 ssthresh/2보다 작으면 slow-start ratio, 아니면 congestion-avoidance ratio를 곱합니다. cwnd와 packets_out의 큰 쪽을 곱하고 srtt_us가 비0이면 나눕니다. 마지막에는 sk_max_pacing_rate와 작은 값을 골라 WRITE_ONCE로 저장합니다. 비율은 sysctl에서 읽으며 이 함수가 개별 패킷 타이머를 직접 예약하는 것은 아닙니다.
 * MSS=1000바이트, cwnd=10, packets_out=8, 실제 RTT=0.1초, 선택 비율=200이라고 가정하면 기본 100000바이트/초의 200%인 200000바이트/초입니다. 최대 pacing rate가 150000이면 저장 결과는 150000입니다. 비트/초와 바이트/초를 혼동하지 않도록 단위를 식 옆에 적으세요.
 */
static void tcp_update_pacing_rate(struct sock *sk)
{
	const struct tcp_sock *tp = tcp_sk(sk);
	u64 rate;

	/* set sk_pacing_rate to 200 % of current rate (mss * cwnd / srtt) */
	rate = (u64)tp->mss_cache * ((USEC_PER_SEC / 100) << 3);

	/* current rate is (cwnd * mss) / srtt
	 * In Slow Start [1], set sk_pacing_rate to 200 % the current rate.
	 * In Congestion Avoidance phase, set it to 120 % the current rate.
	 *
	 * [1] : Normal Slow Start condition is (tp->snd_cwnd < tp->snd_ssthresh)
	 *	 If snd_cwnd >= (tp->snd_ssthresh / 2), we are approaching
	 *	 end of slow start and should slow down.
	 */
	if (tcp_snd_cwnd(tp) < tp->snd_ssthresh / 2)
		rate *= READ_ONCE(sock_net(sk)->ipv4.sysctl_tcp_pacing_ss_ratio);
	else
		rate *= READ_ONCE(sock_net(sk)->ipv4.sysctl_tcp_pacing_ca_ratio);

	rate *= max(tcp_snd_cwnd(tp), tp->packets_out);

	if (likely(tp->srtt_us))
		do_div(rate, tp->srtt_us);

/* 학습 해설
 * Mempool 할당: 일반 할당을 먼저 하고 예약분을 남기기
 * 메모리를 회수하는 I/O 경로가 다시 메모리를 요구하면, 메모리 부족 때문에 회수를 진행하지 못하는 의존성이 생길 수 있습니다. 미리 확보한 작은 예약 풀은 이런 진행 경로에 필요한 객체를 남기는 데 쓰입니다.
 * mempool_alloc_noprof는 NOMEMALLOC·NORETRY·NOWARN을 추가하고 첫 시도에서는 DIRECT_RECLAIM과 IO를 뺀 플래그로 pool->alloc을 부릅니다. 일반 할당이 성공하면 예약분을 건드리지 않습니다. 실패하면 잠금 아래 curr_nr이 있을 때 예약 요소를 꺼내고 unlock 뒤 쓰기 장벽과 kmemleak 추적 갱신 후 반환합니다. 풀이 비었고 첫 제한 플래그였다면 원래 허용 범위로 재시도합니다. 그래도 없고 DIRECT_RECLAIM이 허용되지 않으면 NULL입니다. 대기가 허용되면 wait를 등록하고 잠금을 푼 뒤 5*HZ 타임아웃 대기, finish_wait 후 다시 시도합니다.
 * 예약 요소가 2개 있고 일반 alloc이 성공하면 curr_nr은 2입니다. 일반 alloc이 실패하고 예약을 하나 꺼내면 1입니다. 예약 0에서 기다릴 수 없는 요청은 NULL일 수 있습니다. 풀이 있다고 무한한 동시 요청이 항상 즉시 성공하거나 잠금 의존성 문제까지 자동 해결되는 것은 아닙니다.
 */
void *mempool_alloc_noprof(mempool_t *pool, gfp_t gfp_mask)
{
	void *element;
	unsigned long flags;
	wait_queue_entry_t wait;
	gfp_t gfp_temp;

	VM_WARN_ON_ONCE(gfp_mask & __GFP_ZERO);
	might_alloc(gfp_mask);

	gfp_mask |= __GFP_NOMEMALLOC;	/* don't allocate emergency reserves */
	gfp_mask |= __GFP_NORETRY;	/* don't loop in __alloc_pages */
	gfp_mask |= __GFP_NOWARN;	/* failures are OK */

	gfp_temp = gfp_mask & ~(__GFP_DIRECT_RECLAIM|__GFP_IO);

repeat_alloc:

	element = pool->alloc(gfp_temp, pool->pool_data);
	if (likely(element != NULL))
		return element;

	spin_lock_irqsave(&pool->lock, flags);
	if (likely(pool->curr_nr)) {
		element = remove_element(pool);
		spin_unlock_irqrestore(&pool->lock, flags);

/* 학습 해설
 * Mempool 예약 전용 조회: 잠들지 않고 현재 요소만 꺼내기
 * 어떤 실행 문맥에서는 일반 allocator를 부르거나 객체가 돌아올 때까지 기다릴 수 없습니다. 지금 예약해 둔 요소가 있으면 쓰고 없으면 즉시 다른 경로를 택하도록 별도 API가 있습니다.
 * mempool_alloc_preallocated는 IRQ 상태를 저장하며 pool lock을 잡고 curr_nr을 봅니다. 있으면 remove_element로 꺼내 잠금을 풀고 smp_wmb 및 kmemleak_update_trace 후 반환합니다. 비었으면 잠금을 풀고 NULL입니다. pool->alloc 호출이나 waitqueue 등록, schedule 호출이 없습니다. 여기의 잠들지 않는다는 계약을 일반 mempool_alloc의 대기 가능성과 구별합니다.
 * curr_nr=1이면 한 호출이 예약 요소를 얻고 다음 호출은 반환이 있기 전까지 NULL입니다. 원래 시스템에 여유 메모리가 많아도 이 helper는 새 요소를 일반 할당해 오지 않습니다. 성공한 요소는 나중에 mempool_free로 돌려 풀의 보충 정책에 맞춰 정리합니다.
 */
void *mempool_alloc_preallocated(mempool_t *pool)
{
	void *element;
	unsigned long flags;

	spin_lock_irqsave(&pool->lock, flags);
	if (likely(pool->curr_nr)) {
		element = remove_element(pool);
		spin_unlock_irqrestore(&pool->lock, flags);
		/* paired with rmb in mempool_free(), read comment there */
		smp_wmb();
		/*
		 * Update the allocation stack trace as this is more useful
		 * for debugging.
		 */
		kmemleak_update_trace(element);
		return element;
	}
	spin_unlock_irqrestore(&pool->lock, flags);

	return NULL;
}
EXPORT_SYMBOL(mempool_alloc_preallocated);

