/* 학습 해설
 * 드라이버 probe: 장치 상태·전원 준비·진행 중 개수
 * 드라이버와 장치를 연결할 때 이미 제거된 장치나 다른 드라이버가 붙은 장치를 다시 초기화하면 안 됩니다. 부모 장치 및 공급 장치 전원과 동시에 진행 중인 probe의 상태도 맞춰야 합니다.
 * driver_probe_device는 현재 deferred trigger 수를 읽고 probe_count를 늘린 뒤 __driver_probe_device를 부릅니다. 내부 함수는 dead 또는 미등록 장치에 -ENODEV, 기존 driver가 있으면 -EBUSY입니다. 통과하면 can_match를 설정하고 공급 장치 및 부모 runtime PM 참조를 준비하고 장치 PM barrier 뒤 really_probe 또는 debug 변형을 호출합니다. 이후 idle 요청과 부모·공급자 참조 반환을 수행합니다. 바깥은 양쪽 부호의 EPROBE_DEFER를 처리하고 마지막에 probe_count를 줄여 대기자를 깨우며 ret를 반환합니다.
 * 초기 probe_count=2이면 호출 중 3, 내부 실패로 돌아와도 정상 반환 경로에서 다시 2입니다. 모든 실패가 음수라고 가정하지 마세요. 이 인터페이스 주석은 probe callback 실패가 뒤집힌 양수 코드로 올 수도 있다고 명시하고 defer 조건도 양쪽을 비교합니다. 호출자는 장치 lock을 보유해야 하며 USB interface는 부모 lock 조건도 있습니다.
 */
static int driver_probe_device(const struct device_driver *drv, struct device *dev)
{
	int trigger_count = atomic_read(&deferred_trigger_count);
	int ret;

	atomic_inc(&probe_count);
	ret = __driver_probe_device(drv, dev);
	if (ret == -EPROBE_DEFER || ret == EPROBE_DEFER) {
		driver_deferred_probe_add(dev);

		/*
		 * Did a trigger occur while probing? Need to re-trigger if yes
		 */
		if (trigger_count != atomic_read(&deferred_trigger_count) &&
		    !defer_all_probes)
			driver_deferred_probe_trigger();
	}
	atomic_dec(&probe_count);
	wake_up_all(&probe_waitqueue);
	return ret;
}

