	bool async_drv;

/* 학습 해설
 * 지연 probe: 준비된 공급자를 놓치지 않도록 다시 깨우기
 * 장치 A가 공급자 B를 기다리는데 B가 막 준비된 순간 A가 지연 목록에 들어가면, B의 재시도 알림을 놓칠 수 있습니다. 단순히 목록을 두는 것 외에 probe 중 알림이 발생했는지도 추적해야 합니다.
 * driver_deferred_probe_add는 can_match가 아니면 건너뛰고 mutex 아래 아직 목록에 없는 장치를 pending 끝에 넣습니다. trigger는 기능이 켜진 경우 mutex 아래 trigger_count를 증가시키고 pending 전체를 active 끝으로 옮겨 pending을 초기화합니다. 잠금 해제 뒤 workqueue를 예약합니다. driver_probe_device는 시작 때 기록한 count와 defer 후 count가 다르고 defer_all_probes도 아니면 다시 trigger합니다. del은 mutex 아래 목록에서 빼고 이유를 정리합니다.
 * A의 probe 시작 count=10 → B 성공으로 trigger=11 → A가 defer되어 pending에 들어옴을 그리세요. A는 10과 11의 차이를 보고 재trigger해 자신이 이전 알림 뒤에 들어간 상황을 보완합니다. trigger 자체가 모든 probe를 동기적으로 다시 실행하거나 모든 의존성 해결을 보장하는 함수는 아닙니다.
 */
void driver_deferred_probe_trigger(void)
{
	if (!driver_deferred_probe_enable)
		return;

	/*
	 * A successful probe means that all the devices in the pending list
	 * should be triggered to be reprobed.  Move all the deferred devices
	 * into the active list so they can be retried by the workqueue
	 */
	mutex_lock(&deferred_probe_mutex);
	atomic_inc(&deferred_trigger_count);
	list_splice_tail_init(&deferred_probe_pending_list,
			      &deferred_probe_active_list);
	mutex_unlock(&deferred_probe_mutex);

	/*
	 * Kick the re-probe thread.  It may already be scheduled, but it is
	 * safe to kick it again.
	 */
	queue_work(system_unbound_wq, &deferred_probe_work);
}

