/* 학습 해설
 * DMA 페이지 매핑: CPU 주소와 장치 주소를 구분하기
 * CPU가 접근하는 주소와 장치가 DMA로 사용하는 주소가 항상 같지는 않습니다. IOMMU나 플랫폼의 주소 제약 및 캐시 일관성 처리가 필요할 수 있어 드라이버는 변환 API의 결과와 실패를 확인해야 합니다.
 * dma_map_page_attrs는 DMA 방향이 잘못되면 BUG이고 장치 dma_mask가 없으면 경고 후 DMA_MAPPING_ERROR입니다. 직접 매핑 조건 또는 아키텍처 직접 매핑 조건이면 direct helper, IOMMU 경로이면 iommu helper, 나머지는 ops->map_page를 호출합니다. KMSAN·추적·debug hook 뒤 dma_addr_t를 반환합니다. dma_unmap_page_attrs도 방향을 검사하고 대응 경로로 해제한 뒤 추적·debug를 수행합니다.
 * page와 offset=128,size=1024를 매핑하면 장치에 줄 주소는 반환된 dma_addr_t입니다. CPU 포인터로 캐스팅해 직접 읽는 주소로 취급하지 않습니다. 고정 원문 DMA 안내서의 순서는 map → dma_mapping_error 확인 → 장치 사용 → DMA 종료 확인 → 같은 계약의 unmap입니다. 이 helper 자체가 장치 전송 명령을 시작하지 않습니다.
 */
dma_addr_t dma_map_page_attrs(struct device *dev, struct page *page,
		size_t offset, size_t size, enum dma_data_direction dir,
		unsigned long attrs)
{
	const struct dma_map_ops *ops = get_dma_ops(dev);
	dma_addr_t addr;

	BUG_ON(!valid_dma_direction(dir));

	if (WARN_ON_ONCE(!dev->dma_mask))
		return DMA_MAPPING_ERROR;

	if (dma_map_direct(dev, ops) ||
	    arch_dma_map_page_direct(dev, page_to_phys(page) + offset + size))
		addr = dma_direct_map_page(dev, page, offset, size, dir, attrs);
	else if (use_dma_iommu(dev))
		addr = iommu_dma_map_page(dev, page, offset, size, dir, attrs);
	else
		addr = ops->map_page(dev, page, offset, size, dir, attrs);
	kmsan_handle_dma(page, offset, size, dir);
	trace_dma_map_page(dev, page_to_phys(page) + offset, addr, size, dir,
			   attrs);
	debug_dma_map_page(dev, page, offset, size, dir, addr, attrs);

	return addr;
}

/* 학습 해설
 * DMA sg_table: 원래 항목 수를 보존하고 errno를 전달하기
