/// Transform a kernel "error pointer" to a normal pointer.
///
/// Some kernel C API functions return an "error pointer" which optionally
/// embeds an `errno`. Callers are supposed to check the returned pointer
/// for errors. This function performs the check and converts the "error pointer"
/// to a normal pointer in an idiomatic fashion.
///
/// # Examples
///
/// ```ignore
/// # use kernel::from_err_ptr;
/// # use kernel::bindings;
/// fn devm_platform_ioremap_resource(
///     pdev: &mut PlatformDevice,
///     index: u32,
/// ) -> Result<*mut core::ffi::c_void> {
///     // SAFETY: `pdev` points to a valid platform device. There are no safety requirements
///     // on `index`.

/* 학습 해설
 * Rust 오류 포인터 변환: Ok(raw pointer)가 유효 참조라는 뜻은 아니다
 * 일부 C API는 정상 포인터와 오류 번호를 인코딩한 포인터를 같은 반환형으로 전달합니다. Rust 쪽에서 이를 Result로 구별해도 원래 포인터의 수명·정렬·NULL 여부까지 자동으로 검증되는 것은 아닙니다.
 * from_err_ptr는 포인터를 const void 포인터로 cast하고 C의 IS_ERR를 호출합니다. 오류이면 PTR_ERR로 음수 번호를 꺼내고 범위가 이미 보장됐다는 근거로 from_errno_unchecked를 사용해 Err입니다. 아니면 원래 raw pointer를 Ok로 돌려줍니다. IS_ERR는 메모리를 역참조하지 않고 오류 인코딩 범위를 검사합니다. 이 Rust wrapper도 포인터 자체를 읽지 않으므로 함수가 safe여도 반환된 raw pointer의 역참조가 자동으로 안전해지는 것은 아닙니다.
 * 정상 주소 P는 Ok(P), ERR_PTR(-ENOMEM)은 Err(ENOMEM)입니다. NULL은 IS_ERR_OR_NULL이 아닌 IS_ERR만 검사하므로 Ok(NULL)이 될 수 있습니다. 호출자는 원래 C API의 NULL 규약과 객체 수명을 따로 확인해야 합니다. 반대 방향의 Error::to_ptr는 ERR_PTR로 오류를 인코딩하며 실제 T 객체를 할당하지 않습니다.
 */
pub(crate) fn from_err_ptr<T>(ptr: *mut T) -> Result<*mut T> {
    // CAST: Casting a pointer to `*const core::ffi::c_void` is always valid.
    let const_ptr: *const core::ffi::c_void = ptr.cast();
    // SAFETY: The FFI function does not deref the pointer.
    if unsafe { bindings::IS_ERR(const_ptr) } {
        // SAFETY: The FFI function does not deref the pointer.
        let err = unsafe { bindings::PTR_ERR(const_ptr) };
        // CAST: If `IS_ERR()` returns `true`,
        // then `PTR_ERR()` is guaranteed to return a
        // negative value greater-or-equal to `-bindings::MAX_ERRNO`,
        // which always fits in an `i16`, as per the invariant above.
        // And an `i16` always fits in an `i32`. So casting `err` to
        // an `i32` can never overflow, and is always valid.
        //
        // SAFETY: `IS_ERR()` ensures `err` is a
        // negative value greater-or-equal to `-bindings::MAX_ERRNO`.
        #[allow(clippy::unnecessary_cast)]
        return Err(unsafe { Error::from_errno_unchecked(err as core::ffi::c_int) });
    }
    Ok(ptr)
}

