/// a C integer result.
///
/// This is useful when calling Rust functions that return [`crate::error::Result<T>`]

/* 학습 해설
 * Rust에서 C callback으로: closure 결과를 errno 정수로 바꾸기
 * Rust 내부에서 ?로 오류를 전파하더라도 C가 부르는 callback은 C 규약의 정수를 반환해야 할 수 있습니다. 변환 경계를 한 곳에 두면 Rust 내부의 Result 처리와 외부 ABI를 연결할 수 있습니다.
 * from_result는 FnOnce()->Result<T>인 closure f를 한 번 호출합니다. Ok(v)는 v를 그대로 반환하고 Err(e)는 음수 errno를 i16으로 바꾼 뒤 T::from으로 변환합니다. T:From<i16> 제약이 있어 해당 오류 값을 표현할 변환이 제공되어야 합니다. Error의 범위 불변 조건 때문에 음수 errno는 i16에 들어가므로 이 캐스팅에서 범위를 잃지 않는다는 근거를 원문이 명시합니다.
 * T를 C int에 해당하는 타입으로 두면 closure가 Ok(7)일 때 반환 7, Err(ENOMEM)이면 음수 ENOMEM 값입니다. to_result와 달리 성공 값 v를 보존합니다. FnOnce는 성공 확인과 오류 확인을 위해 closure를 두 번 실행하지 않는 계약으로 읽으세요.
 */
pub(crate) fn from_result<T, F>(f: F) -> T
where
    T: From<i16>,
    F: FnOnce() -> Result<T>,
{
    match f() {
        Ok(v) => v,
        // NO-OVERFLOW: negative `errno`s are no smaller than `-bindings::MAX_ERRNO`,
        // `-bindings::MAX_ERRNO` fits in an `i16` as per invariant above,
        // therefore a negative `errno` always fits in an `i16` and will not overflow.
        Err(e) => T::from(e.to_errno() as i16),
    }
}

