/* 학습 해설
 * 모듈 동시 로딩: inode 해시와 완료 알림으로 결과 공유하기
 * 두 프로세스가 같은 모듈 파일을 동시에 요청하면 파일 읽기와 로딩을 중복 실행할 수 있습니다. 먼저 시작한 요청 하나가 작업하고 나머지가 같은 결과를 받으면 중복 비용을 줄입니다.
 * idempotent_init_module은 유효한 읽기 가능 file인지 검사하고 아니면 -EBADF입니다. file_inode(f)를 cookie로 idempotent에 넘깁니다. idempotent는 256개 버킷 중 hash_ptr로 고른 목록을 idem_lock 아래 검사하며 cookie가 같은 기존 요청이 있는지 찾습니다. 각 요청은 자기 노드를 추가합니다. 첫 요청이면 false가 반환되어 파일 로딩을 실행하고 idempotent_complete로 결과를 공유합니다. 후발 요청이면 완료를 기다립니다.
 * A가 inode X로 먼저 등록하면 A가 로딩합니다. B가 A의 작업 중 같은 X로 등록하면 B는 기다립니다. C가 다른 inode Y인데 해시 버킷만 같다면 cookie 비교가 다르므로 자체 작업을 할 수 있습니다. 해시 충돌과 같은 요청은 다릅니다.
 */
static int idempotent_init_module(struct file *f, const char __user * uargs, int flags)
{
	struct idempotent idem;

	if (!f || !(f->f_mode & FMODE_READ))
		return -EBADF;

	/* Are we the winners of the race and get to do this? */
	if (!idempotent(&idem, file_inode(f))) {
		int ret = init_module_from_file(f, uargs, flags);
		return idempotent_complete(&idem, ret);
	}

	/*
	 * Somebody else won the race and is loading the module.
	 */
	return idempotent_wait_for_completion(&idem);
}

