	case S_INT:
		val->s = strtoll(str, &tail, 10);
		kind = k_signed;
		break;
	case S_HEX:
		val->u = strtoull(str, &tail, 16);
		kind = k_unsigned;
		break;
	default:
		val->s = strtoll(str, &tail, 0);
		kind = k_signed;

/* 학습 해설
 * 모듈 로딩 진입 정책: 권한·비활성 설정·허용 플래그
 * 모듈은 커널 내부에서 실행되는 코드를 추가하므로 일반 파일 읽기 권한만으로 로딩을 허용하면 안 됩니다. 로더는 내용을 읽기 전에 요청자의 권한과 로딩 중지 설정부터 검사합니다.
