	 * Anonymous folios are not handled by flushers and must be written
	 * from reclaim context. Do not stall reclaim based on them.
	 * MADV_FREE anonymous folios are put into inactive file list too.
	 * They could be mistakenly treated as file lru. So further anon
	 * test is needed.
	 */
	if (!folio_is_file_lru(folio) ||
	    (folio_test_anon(folio) && !folio_test_swapbacked(folio))) {
		*dirty = false;
		*writeback = false;
		return;
	}

	/* By default assume that the folio flags are accurate */
	*dirty = folio_test_dirty(folio);
	*writeback = folio_test_writeback(folio);

	/* Verify dirty/writeback state if the filesystem supports it */
	if (!folio_test_private(folio))
		return;

/* 학습 해설
 * IPv4 다음 홉 검사: DEAD·LINKDOWN·출력 인터페이스는 다른 조건
 * 목적지 prefix가 맞아도 사용할 수 없는 다음 홉이면 패킷을 내보낼 경로로 선택하면 안 됩니다. 반대로 링크 상태를 무시하라는 검색 정책이 있어도 죽은 경로 표시나 출력 인터페이스 지정까지 모두 무시하면 잘못된 결과가 됩니다.
 * fib_lookup_good_nhc는 RTNH_F_DEAD가 있으면 먼저 false입니다. 다음은 ip_ignore_linkdown이 참이고 RTNH_F_LINKDOWN이 있고 검색 flags에 FIB_LOOKUP_IGNORE_LINKSTATE가 없을 때 false입니다. 마지막으로 요청 flowi4_oif가 0이 아니면서 다음 홉의 nhc_oif와 다르면 false이고, 나머지는 true입니다. 각 거절 사유가 별도 조건문입니다.
 * LINKDOWN 표시가 있어도 링크 무시 정책이 꺼져 있거나 검색이 IGNORE_LINKSTATE를 지정하면 그 분기는 통과할 수 있습니다. 그러나 DEAD까지 동시에 있으면 첫 분기에서 이미 false입니다. 요청 oif=3이고 다음 홉 oif=4이면 링크 상태와 무관하게 false입니다. oif=0이면 특정 출력 인터페이스 제한을 걸지 않습니다.
 */
bool fib_lookup_good_nhc(const struct fib_nh_common *nhc, int fib_flags,
			 const struct flowi4 *flp)
{
	if (nhc->nhc_flags & RTNH_F_DEAD)
		return false;

	if (ip_ignore_linkdown(nhc->nhc_dev) &&
	    nhc->nhc_flags & RTNH_F_LINKDOWN &&
	    !(fib_flags & FIB_LOOKUP_IGNORE_LINKSTATE))
		return false;

	if (flp->flowi4_oif && flp->flowi4_oif != nhc->nhc_oif)
		return false;

	return true;
}

/* should be called with rcu_read_lock */
int fib_table_lookup(struct fib_table *tb, const struct flowi4 *flp,
		     struct fib_result *res, int fib_flags)
{
	struct trie *t = (struct trie *) tb->tb_data;
#ifdef CONFIG_IP_FIB_TRIE_STATS
	struct trie_use_stats __percpu *stats = t->stats;
#endif
	const t_key key = ntohl(flp->daddr);

/* 학습 해설
 * IPv4 trie 검색: 더 긴 prefix 실패 후 되돌아가는 과정
 * 목적지 주소에 더 구체적으로 맞는 경로를 먼저 시도하되, 그 후보가 없거나 정책상 사용할 수 없다면 더 넓은 경로를 찾아야 합니다. 압축 trie는 공통 prefix와 여러 비트의 분기를 묶어 주소마다 거대한 배열을 만드는 비용을 피합니다.
 * fib_table_lookup은 RCU 읽기 잠금을 가진 호출자를 요구합니다. 목적지 주소를 ntohl로 key로 바꾸고 get_cindex의 XOR와 shift로 자식 인덱스를 구합니다. index가 1ul<<bits 이상이면 건너뛴 prefix 비트 불일치가 포함된 것으로 처리합니다. leaf 도달 후 alias의 prefix 범위·DSCP·dead·scope와 다음 홉 조건을 검사합니다. 의미상 쓸 수 없는 후보는 다음 후보 또는 backtrace로 갑니다. backtrace는 cindex가 0이면 부모로 올라가고 그렇지 않으면 cindex &= cindex-1로 최하위 1비트를 지워 다음 후보 자식을 찾습니다.
 * 되돌아가기 인덱스가 이진수 1100이면 cindex-1=1011이고 AND 결과는 1000입니다. 다음에는 1000&0111=0000입니다. 이것은 모든 인덱스를 하나씩 감소시키는 것과 다릅니다. 0이 되면 부모 후보로 올라가는 경로가 필요합니다. trie 끝까지 후보가 없으면 -EAGAIN이며 곧바로 네트워크 전체에 경로가 없다는 최종 판정으로 확대하면 안 됩니다.
 */
int fib_table_lookup(struct fib_table *tb, const struct flowi4 *flp,
		     struct fib_result *res, int fib_flags)
{
	struct trie *t = (struct trie *) tb->tb_data;
#ifdef CONFIG_IP_FIB_TRIE_STATS
	struct trie_use_stats __percpu *stats = t->stats;
#endif
	const t_key key = ntohl(flp->daddr);
	struct key_vector *n, *pn;
	struct fib_alias *fa;
	unsigned long index;
	t_key cindex;

	pn = t->kv;
	cindex = 0;

	n = get_child_rcu(pn, cindex);
	if (!n) {
		trace_fib_table_lookup(tb->tb_id, flp, NULL, -EAGAIN);
		return -EAGAIN;
	}

#ifdef CONFIG_IP_FIB_TRIE_STATS
	this_cpu_inc(stats->gets);
#endif

/* 학습 해설
 * ext4 비트맵: 1비트 상태에서 빈 자원 수 계산하기
 * 한 자원의 사용 여부만 필요할 때 주소나 큰 정수를 저장할 이유는 없습니다. 1비트로 사용 중과 비어 있음을 표시하면 조밀한 고정 범위의 자원 상태를 작게 저장할 수 있습니다. 8192개 상태는 1024바이트이며 4바이트 정수 배열의 32768바이트보다 작습니다.
 * ext4_count_free는 numchars*BITS_PER_BYTE에서 memweight(bitmap,numchars)를 뺍니다. memweight는 지정된 메모리 구간에서 켜진 비트 수입니다. 따라서 전체 비트에서 1인 비트를 빼 0인 비트 수를 구합니다. 이 helper는 비트를 바꾸거나 자원을 할당하지 않습니다. 입력 길이도 검사하지 않으므로 호출자가 유효한 버퍼와 범위를 제공해야 합니다.
 * 두 바이트가 00001111과 10000000이면 전체 16비트 중 켜진 비트는 4+1=5개이고 반환값은 11입니다. inode 비트맵은 inode 테이블 항목의 사용 상태를 나타냅니다. 블록 비트맵을 해석할 때는 bigalloc의 cluster 단위 등 파일시스템 형식도 확인해야 하며 이 함수는 의미를 모르는 일반 비트 수 계산입니다.
 */
unsigned int ext4_count_free(char *bitmap, unsigned int numchars)
{
	return numchars * BITS_PER_BYTE - memweight(bitmap, numchars);
}

int ext4_inode_bitmap_csum_verify(struct super_block *sb,
				  struct ext4_group_desc *gdp,
				  struct buffer_head *bh)
{
	__u32 hi;
	__u32 provided, calculated;
	struct ext4_sb_info *sbi = EXT4_SB(sb);
	int sz;

	if (!ext4_has_metadata_csum(sb))
		return 1;

	sz = EXT4_INODES_PER_GROUP(sb) >> 3;
	provided = le16_to_cpu(gdp->bg_inode_bitmap_csum_lo);
	calculated = ext4_chksum(sbi, sbi->s_csum_seed, (__u8 *)bh->b_data, sz);
	if (sbi->s_desc_size >= EXT4_BG_INODE_BITMAP_CSUM_HI_END) {
		hi = le16_to_cpu(gdp->bg_inode_bitmap_csum_hi);
		provided |= (hi << 16);
	} else
		calculated &= 0xFFFF;

/* 학습 해설
 * ext4 inode 비트맵 체크섬: 16비트와 32비트 비교의 차이
 * 디스크에서 읽은 비트맵이 손상되면 이미 사용 중인 inode를 비어 있다고 오해할 수 있습니다. 저장된 체크섬과 현재 데이터로 계산한 체크섬을 비교해 손상을 탐지하되 디스크 형식이 저장할 수 있는 체크섬 폭에 맞춰야 합니다.
 * ext4_inode_bitmap_csum_verify는 metadata_csum 기능이 없으면 1을 반환합니다. 기능이 있으면 INODES_PER_GROUP>>3 바이트에 대해 s_csum_seed로 ext4_chksum을 계산합니다. 저장된 low16은 le16_to_cpu로 읽습니다. descriptor 크기가 high 필드 끝 위치 이상이면 high16을 읽어 16비트 왼쪽으로 옮겨 합칩니다. 그렇지 않으면 계산 결과를 0xFFFF로 마스킹합니다. 마지막 반환은 provided==calculated입니다.
 * 계산 결과가 0x1234ABCD이고 짧은 descriptor에 low=0xABCD이면 비교는 통과합니다. 긴 descriptor라면 high=0x1234도 필요합니다. high=0x5678이면 0x5678ABCD와 비교하므로 실패합니다. INODES_PER_GROUP=8192인 정상 형식이면 계산 범위는 1024바이트입니다.
 */
int ext4_inode_bitmap_csum_verify(struct super_block *sb,
				  struct ext4_group_desc *gdp,
				  struct buffer_head *bh)
{
	__u32 hi;
	__u32 provided, calculated;
	struct ext4_sb_info *sbi = EXT4_SB(sb);
	int sz;

	if (!ext4_has_metadata_csum(sb))
		return 1;

	sz = EXT4_INODES_PER_GROUP(sb) >> 3;
	provided = le16_to_cpu(gdp->bg_inode_bitmap_csum_lo);
	calculated = ext4_chksum(sbi, sbi->s_csum_seed, (__u8 *)bh->b_data, sz);
	if (sbi->s_desc_size >= EXT4_BG_INODE_BITMAP_CSUM_HI_END) {
		hi = le16_to_cpu(gdp->bg_inode_bitmap_csum_hi);
		provided |= (hi << 16);
	} else
		calculated &= 0xFFFF;

	return provided == calculated;
}

void ext4_inode_bitmap_csum_set(struct super_block *sb,
				struct ext4_group_desc *gdp,

/* 학습 해설
 * ext4 체크섬 저장: cluster 범위와 메모리 갱신의 책임
 * 비트맵 내용을 바꾼 뒤 체크섬도 새 내용에 맞춰야 다음 검사가 이전 데이터의 체크섬과 비교하지 않습니다. 다만 체크섬 필드를 메모리에서 바꾸는 것과 디스크에 안전하게 기록하는 것은 별도 작업입니다.
 * ext4_block_bitmap_csum_set은 CLUSTERS_PER_GROUP/8 바이트를 사용합니다. metadata_csum이 없으면 아무 필드도 쓰지 않습니다. 있으면 seed로 계산한 값의 low16을 cpu_to_le16으로 저장하고 descriptor가 high 필드를 포함하면 high16도 저장합니다. inode setter는 같은 구조이지만 INODES_PER_GROUP>>3 범위와 inode 체크섬 필드를 사용합니다. block verifier도 cluster 범위로 계산하며 low/high 결합 또는 16비트 마스킹 후 일치를 검사합니다.
 * 계산값 0x1234ABCD이면 low 필드의 숫자 값은 0xABCD, high 필드는 0x1234입니다. 디스크 little-endian 바이트로 low는 CD AB, high는 34 12입니다. 짧은 descriptor이면 high를 쓰지 않습니다. CLUSTERS_PER_GROUP=32768이면 계산 구간은 4096바이트입니다. bigalloc에서는 cluster 하나에 여러 블록이 들어갈 수 있어 블록 수와 cluster 수를 무조건 같다고 할 수 없습니다.
 */
void ext4_block_bitmap_csum_set(struct super_block *sb,
				struct ext4_group_desc *gdp,
				struct buffer_head *bh)
{
	int sz = EXT4_CLUSTERS_PER_GROUP(sb) / 8;
	__u32 csum;
	struct ext4_sb_info *sbi = EXT4_SB(sb);

	if (!ext4_has_metadata_csum(sb))
		return;

	csum = ext4_chksum(sbi, sbi->s_csum_seed, (__u8 *)bh->b_data, sz);
	gdp->bg_block_bitmap_csum_lo = cpu_to_le16(csum & 0xFFFF);
	if (sbi->s_desc_size >= EXT4_BG_BLOCK_BITMAP_CSUM_HI_END)
		gdp->bg_block_bitmap_csum_hi = cpu_to_le16(csum >> 16);
}
